     1	package shop.web;
     2	
     3	import com.fasterxml.jackson.core.JsonGenerator;
     4	import com.fasterxml.jackson.databind.JsonNode;
     5	import com.fasterxml.jackson.databind.ObjectMapper;
     6	import com.fasterxml.jackson.databind.SerializationFeature;
     7	import com.fasterxml.jackson.databind.node.JsonNodeFactory;
     8	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
     9	import io.javalin.Javalin;
    10	import io.javalin.http.Context;
    11	import shop.ApiException;
    12	import shop.QueryService;
    13	import shop.checkout.CheckoutRequest;
    14	import shop.order.OrderService;
    15	
    16	import java.util.Map;
    17	import java.util.function.Supplier;
    18	
    19	public final class Routes {
    20	    private static final ObjectMapper MAPPER = new ObjectMapper()
    21	            .registerModule(new JavaTimeModule())
    22	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    23	            .enable(JsonGenerator.Feature.WRITE_BIGDECIMAL_AS_PLAIN);
    24	
    25	    private final OrderService orders;
    26	    private final QueryService queries;
    27	
    28	    public Routes(OrderService orders, QueryService queries) {
    29	        this.orders = orders;
    30	        this.queries = queries;
    31	    }
    32	
    33	    public void register(Javalin app) {
    34	        app.post("/checkout/summary", ctx -> reply(ctx, 200, () -> orders.summary(CheckoutRequest.from(body(ctx)))));
    35	        app.post("/orders", ctx -> reply(ctx, 201, () -> orders.register(CheckoutRequest.from(body(ctx)))));
    36	        app.get("/orders/{id}", ctx -> reply(ctx, 200, () -> orders.get(ctx.pathParam("id"))));
    37	        app.post("/orders/{id}/payment", ctx -> reply(ctx, 200, () -> orders.confirmPayment(ctx.pathParam("id"), body(ctx))));
    38	        app.post("/orders/{id}/shipment", ctx -> reply(ctx, 200, () -> orders.ship(ctx.pathParam("id"), body(ctx))));
    39	        app.post("/orders/{id}/delivery", ctx -> reply(ctx, 200, () -> orders.deliver(ctx.pathParam("id"))));
    40	        app.post("/orders/{id}/cancellation", ctx -> reply(ctx, 200, () -> orders.cancel(ctx.pathParam("id"))));
    41	        app.get("/products/{sku}", ctx -> reply(ctx, 200, () -> queries.product(ctx.pathParam("sku"))));
    42	        app.get("/customers/{cpf}", ctx -> reply(ctx, 200, () -> queries.customer(ctx.pathParam("cpf"))));
    43	        app.get("/customers/{cpf}/notifications", ctx -> reply(ctx, 200, () -> queries.notifications(ctx.pathParam("cpf"))));
    44	        app.post("/notifications/{id}/read", ctx -> reply(ctx, 200, () -> queries.markRead(ctx.pathParam("id"))));
    45	    }
    46	
    47	    private static JsonNode body(Context ctx) {
    48	        try {
    49	            JsonNode node = MAPPER.readTree(ctx.body());
    50	            return node != null && node.isObject() ? node : JsonNodeFactory.instance.objectNode();
    51	        } catch (Exception e) {
    52	            return JsonNodeFactory.instance.objectNode();
    53	        }
    54	    }
    55	
    56	    private static void reply(Context ctx, int successStatus, Supplier<Object> action) {
    57	        int status = successStatus;
    58	        Object payload;
    59	        try {
    60	            payload = action.get();
    61	        } catch (ApiException e) {
    62	            status = e.status();
    63	            payload = Map.of("error", e.code());
    64	        } catch (RuntimeException e) {
    65	            e.printStackTrace();
    66	            status = 500;
    67	            payload = Map.of("error", "INTERNAL_ERROR");
    68	        }
    69	        try {
    70	            ctx.status(status).contentType("application/json").result(MAPPER.writeValueAsString(payload));
    71	        } catch (Exception e) {
    72	            throw new IllegalStateException(e);
    73	        }
    74	    }
    75	}

