    16	    private static final Duration TIMEOUT = Duration.ofSeconds(2);
    17	
    18	    private final String baseUrl;
    19	    private final HttpClient client = HttpClient.newBuilder().connectTimeout(TIMEOUT).build();
    20	    private final ObjectMapper mapper = new ObjectMapper();
    21	
    22	    public TransLogGateway(String baseUrl) {
    23	        this.baseUrl = baseUrl == null ? null : baseUrl.replaceAll("/+$", "");
    24	    }
    25	
    26	    @Override
    27	    public CarrierQuote quote(String zipCode, int weightGrams, String service) {
    28	        if (baseUrl == null || baseUrl.isBlank()) {
    29	            throw down();
    30	        }
    31	        JsonNode body;
    32	        try {
    33	            URI uri = URI.create(baseUrl + "/v2/quote?zip=" + zipCode + "&weight_g=" + weightGrams + "&service=" + service);
    34	            HttpRequest request = HttpRequest.newBuilder(uri).timeout(TIMEOUT).GET().build();
    35	            HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
    36	            if (response.statusCode() != 200) {
    37	                throw down();
    38	            }
    39	            body = mapper.readTree(response.body());
    40	        } catch (InterruptedException e) {
    41	            Thread.currentThread().interrupt();
    42	            throw down();
    43	        } catch (IOException | RuntimeException e) {
    44	            if (e instanceof ApiException api) {
    45	                throw api;
    46	            }
    47	            throw down();
    48	        }
    49	        if (body == null || !body.isObject()) {
    50	            throw down();
    51	        }
    52	        if (body.has("error")) {
    53	            if ("ZIP_NOT_SERVED".equals(body.get("error").asText())) {
    54	                throw ApiException.unprocessable("SHIPPING_METHOD_UNAVAILABLE");
    55	            }
    56	            throw down();
    57	        }
    58	        JsonNode price = body.get("price_cents");
    59	        JsonNode eta = body.get("eta_hours");
    60	        if (price == null || eta == null || !price.isIntegralNumber() || !eta.isIntegralNumber()
    61	                || !eta.canConvertToInt() || price.asLong() < 0 || eta.asInt() < 0) {
    62	            throw down();
    63	        }
    64	        return new CarrierQuote(BigDecimal.valueOf(price.asLong(), 2), eta.asInt());
    65	    }
    66	
    67	    private static ApiException down() {
    68	        return ApiException.unavailable("CARRIER_UNAVAILABLE");
    69	    }
    70	}
