     8	public enum OrderStatus {
     9	    AWAITING_PAYMENT(false),
    10	    PAID(true),
    11	    SHIPPED(true),
    12	    DELIVERED(true),
    13	    CANCELLED(false);
    14	
    15	    private static final Map<OrderStatus, Set<OrderStatus>> TRANSITIONS = new EnumMap<>(OrderStatus.class);
    16	
    17	    static {
    18	        TRANSITIONS.put(AWAITING_PAYMENT, EnumSet.of(PAID, CANCELLED));
    19	        TRANSITIONS.put(PAID, EnumSet.of(SHIPPED, CANCELLED));
    20	        TRANSITIONS.put(SHIPPED, EnumSet.of(DELIVERED));
    21	        TRANSITIONS.put(DELIVERED, EnumSet.noneOf(OrderStatus.class));
    22	        TRANSITIONS.put(CANCELLED, EnumSet.noneOf(OrderStatus.class));
    23	    }
